#include "ark/agent.hpp"
#include "../src/manufacturing_internal.hpp"
#include <iostream>
using namespace ark;using V=arkjson::Value;
static void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
static V json(const char* s){V v;check(arkjson::parse(s,v),"fixture JSON");return v;}
static V payload(V r){if(r.find("isError")->b)throw std::runtime_error(r.find("structuredContent")->dump());return *r.find("structuredContent");}
int main(){try{
    AgentSession s;payload(s.call("doc_apply",json(R"({"expected_revision":0,"commands":[{"op":"feature.add","type":"native_solid","name":"Bracket A","native":{"op":"box"},"manufacturing":{"route":"additive","process":{"method":"fdm","material_grade":"PLA","build_direction":[0,0,1],"slicer_profile":"PLA 0.2"}},"p":{"width":20,"depth":10,"height":8}},{"op":"feature.add","type":"native_solid","name":"Bracket B","native":{"op":"box"},"manufacturing":{"route":"additive","process":{"method":"fdm","material_grade":"PLA","build_direction":[0,0,1],"slicer_profile":"PLA 0.2"}},"p":{"width":12,"depth":10,"height":8}}]})")));
    V args=json(R"({"action":"prepare_print_job","expected_revision":1,"job":{"name":"Synthetic job","bed_mm":[70,60,50],"gap_mm":5,"margin_mm":5}})");auto before=documentToJson(s.document);auto prepared=payload(s.call("manufacturing_plan",args));check(!prepared.find("blocked")->b&&prepared.find("part_quantity")->num==2&&prepared.find("plates")->arr.size()==1,"automatic additive discovery/grouping");check(documentToJson(s.document)==before&&s.revision==1,"prepare mutated CAD");
    auto job=*args.find("job");job.set("items",json(R"([{"feature":1,"quantity":9,"material":"PLA","profile":"PLA 0.2","cut_group":"A","build_direction":[0,0,1]},{"feature":2,"quantity":2,"material":"PETG","profile":"PETG 0.2","cut_group":"B","build_direction":[0,0,1]}])"));args.set("job",job);prepared=payload(s.call("manufacturing_plan",args));check(!prepared.find("blocked")->b&&prepared.find("part_quantity")->num==11&&prepared.find("plates")->arr.size()==3,"quantity overflow/material groups");
    auto repeat=payload(s.call("manufacturing_plan",args));check(repeat.dump()==prepared.dump(),"plate packing nondeterministic");auto preview=payload(s.call("doc_preview",*prepared.find("preview_arguments")));check(preview.find("valid")->b,preview.dump().c_str());payload(s.call("doc_apply",*preview.find("apply")));check(s.document.manufacturingPlans.arr.size()==3&&s.revision==2,"plate transaction not atomic");
    for(const auto& plan:s.document.manufacturingPlans.arr){mfg::Graph graph(plan);auto mesh=mfg::printPlateMesh062(s.document,graph,graph.data("plate","plate"));check(!mesh.idx.empty(),"placed STL mesh empty");V a=json(R"({"expected_revision":2})");a.set("name",*plan.find("name"));check(s.call("manufacturing_simulate",a).find("isError")->b,"unsliced plan simulated placeholder G-code");}
    Document reopened;std::string error;check(documentFromJson(documentToJson(s.document),reopened,&error),error.c_str());check(mfg::canonical(reopened.manufacturingPlans).dump()==mfg::canonical(s.document.manufacturingPlans).dump(),"plate persistence fields");
    auto& plan=s.document.manufacturingPlans.arr.front();V bad=plan;auto badNodes=*bad.find("nodes");for(auto& n:badNodes.arr)if(n.find("kind")->str=="plate"){auto data=*n.find("data");auto items=*data.find("items");check(items.arr.size()>1,"overlap fixture");items.arr[1].set("placement",*items.arr[0].find("placement"));data.set("items",items);n.set("data",data);}bad.set("nodes",badNodes);bool rejected=false;try{mfg::Graph g(bad);mfg::printPlateMesh062(s.document,g,g.data("plate","plate"));}catch(...){rejected=true;}check(rejected,"overlap sent to slicer");
    args.set("expected_revision",V::makeNum(2));job.set("name",V::makeStr("Oversize"));job.set("bed_mm",json("[15,15,5]"));args.set("job",job);auto blocked=payload(s.call("manufacturing_plan",args));check(blocked.find("blocked")->b&&!blocked.find("preview_arguments"),"oversize silently omitted or scaled");
    job.set("bed_mm",json("[70,60,50]"));job.set("items",json(R"([{"feature":1,"quantity":1,"build_direction":[1,0,0]}])"));job.set("name",V::makeStr("Rotated"));args.set("job",job);check(!payload(s.call("manufacturing_plan",args)).find("blocked")->b,"declared build orientation");
    s.document.evalBodies.back().nativeData.set("brep_base64",V::makeStr("changed"));rejected=false;try{mfg::Graph g(plan);mfg::printPlateMesh062(s.document,g,g.data("plate","plate"));}catch(...){rejected=true;}check(rejected,"stale plate source accepted");
    args.set("expected_revision",V::makeNum(1));check(s.call("manufacturing_plan",args).find("isError")->b,"stale revision accepted");
    std::cout<<"062B print jobs: discovery, quantities, material/cut grouping, multi-plate packing, rigid orientation, atomic preview/apply, persistence, overlap/oversize/stale rejection passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
